const canvas=document.getElementById('world'),ctx=canvas.getContext('2d'),mapC=document.getElementById('mapCanvas'),mctx=mapC.getContext('2d');
const W=2000,H=1350;let vw=innerWidth,vh=innerHeight,dpr=Math.min(devicePixelRatio||1,2),last=0,clock=0,cam={x:0,y:0};
function resize(){vw=innerWidth;vh=innerHeight;dpr=Math.min(devicePixelRatio||1,2);canvas.width=vw*dpr;canvas.height=vh*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}addEventListener('resize',resize);resize();
const state={x:940,y:690,face:1,hp:100,maxHp:100,mp:50,maxMp:50,xp:0,next:100,level:1,gil:40,potions:2,slimes:0,defeated:0,quest:0,selected:null,move:null,attackCd:0,cleaveCd:0,invuln:0,resting:false,inventory:{'Field Potion':2,'Slime Core':0,'Sunpetal':0},name:'Wayfarer',messages:[],interactTarget:null,gameTime:8.5,dead:false};
const trees=[],props=[],mobs=[],particles=[],npcs=[];
let seed=28713;function rand(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296}function rr(a,b){return a+rand()*(b-a)}
// Hand-placed old-road hamlet, ruins, and a meadow full of harmless details.
for(let i=0;i<115;i++){let x=rr(40,W-40),y=rr(45,H-45);if(Math.hypot(x-940,y-690)<145||Math.abs(y-(710+.25*(x-900)))<85)continue;trees.push({x,y,r:rr(20,42),tone:Math.floor(rr(0,4)),kind:rand()>.79?'pine':'broad'})}
for(let i=0;i<310;i++){let x=rr(20,W-20),y=rr(20,H-20);props.push({x,y,k:rand()})}
function addMob(type,x,y,level=1){mobs.push({type,x,y,level,hp:type==='Mossback Boar'?60:44,max:type==='Mossback Boar'?60:44,alive:true,homeX:x,homeY:y,phase:rr(0,8),attack:0,hit:0,aggro:false})}
[["Meadow Slime",750,450],["Meadow Slime",1180,435],["Meadow Slime",1440,690],["Meadow Slime",790,895],["Meadow Slime",1210,985],["Meadow Slime",520,720],["Mossback Boar",1510,420],["Mossback Boar",470,410]].forEach(a=>addMob(...a));
npcs.push({name:'Sentry Elowen',x:835,y:590,kind:'sentinel',icon:'♙',line:'The meadow has been unusually lively. Could you thin the slimes for us?'},{name:'Tomas the Trader',x:1015,y:615,kind:'merchant',icon:'♜',line:'A good blade is worth its weight in gil. Take a look at my wares.'},{name:'Old Rowan',x:1110,y:765,kind:'elder',icon:'♙',line:'Rest beneath the old oak, traveler. Even heroes need a quiet moment.'});
function roundRect(c,x,y,w,h,r){c.beginPath();c.roundRect(x,y,w,h,r)}
function worldToScreen(x,y){return{x:x-cam.x,y:y-cam.y}}
function drawGround(){
 let g=ctx.createLinearGradient(0,0,0,vh);g.addColorStop(0,'#506c54');g.addColorStop(.52,'#65794e');g.addColorStop(1,'#394d3e');ctx.fillStyle=g;ctx.fillRect(0,0,vw,vh);
 // softly blended earth and clover patches
 for(let i=0;i<95;i++){let x=((i*397+73)%W)-cam.x,y=((i*263+119)%H)-cam.y;if(x<-100||x>vw+100||y<-100||y>vh+100)continue;ctx.fillStyle=['rgba(157,157,92,.10)','rgba(29,66,47,.16)','rgba(190,166,96,.08)','rgba(57,95,67,.23)'][i%4];ctx.beginPath();ctx.ellipse(x,y,rr(36,105),rr(18,64),rr(-1,1),0,Math.PI*2);ctx.fill()}
 // winding ochre road
 ctx.beginPath();ctx.moveTo(-cam.x-50,730-cam.y);ctx.bezierCurveTo(420-cam.x,680-cam.y,570-cam.x,830-cam.y,890-cam.x,725-cam.y);ctx.bezierCurveTo(1160-cam.x,620-cam.y,1340-cam.x,710-cam.y,2050-cam.x,548-cam.y);ctx.strokeStyle='#7d7150';ctx.lineWidth=106;ctx.stroke();ctx.strokeStyle='rgba(204,182,127,.23)';ctx.lineWidth=83;ctx.stroke();
 // shallow creek, upper meadow
 ctx.beginPath();ctx.moveTo(-cam.x+1070,-cam.y);ctx.bezierCurveTo(1010-cam.x,260-cam.y,1320-cam.x,270-cam.y,1240-cam.x,480-cam.y);ctx.bezierCurveTo(1190-cam.x,600-cam.y,1400-cam.x,650-cam.y,1380-cam.x,800-cam.y);ctx.strokeStyle='#446b6a';ctx.lineWidth=47;ctx.stroke();ctx.strokeStyle='rgba(130,183,174,.36)';ctx.lineWidth=32;ctx.stroke();
 // village square and buildings
 drawBuilding(690,510,118,92,'THE WAYFARER\'S REST','#755c44');drawBuilding(1035,500,108,83,'SUPPLIES','#6a5945');drawBuilding(870,420,72,61,'','#785e46');
 // stone well
 let q=worldToScreen(965,635);ctx.fillStyle='#252a26';ctx.beginPath();ctx.ellipse(q.x,q.y+9,27,15,0,0,7);ctx.fill();ctx.fillStyle='#8c8a77';ctx.beginPath();ctx.ellipse(q.x,q.y,24,13,0,0,7);ctx.fill();ctx.fillStyle='#334a48';ctx.beginPath();ctx.ellipse(q.x,q.y-2,14,7,0,0,7);ctx.fill();ctx.strokeStyle='#9d906b';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(q.x-20,q.y-5);ctx.lineTo(q.x-20,q.y-28);ctx.lineTo(q.x+20,q.y-28);ctx.lineTo(q.x+20,q.y-5);ctx.stroke();
}
function drawBuilding(x,y,w,h,label,roof){let p=worldToScreen(x,y);ctx.fillStyle='rgba(0,0,0,.26)';ctx.fillRect(p.x-w/2+8,p.y-h/2+24,w,h);ctx.fillStyle='#b5a27c';ctx.fillRect(p.x-w/2,p.y-h/2+10,w,h-10);ctx.fillStyle='#655744';ctx.fillRect(p.x-w/2+12,p.y-h/2+29,w-24,h-31);ctx.fillStyle='#423b30';ctx.fillRect(p.x-10,p.y+4,20,h/2);ctx.fillStyle=roof;ctx.beginPath();ctx.moveTo(p.x-w/2-9,p.y-h/2+14);ctx.lineTo(p.x,p.y-h/2-27);ctx.lineTo(p.x+w/2+9,p.y-h/2+14);ctx.closePath();ctx.fill();ctx.strokeStyle='rgba(220,192,132,.3)';ctx.lineWidth=2;ctx.stroke();if(label){ctx.fillStyle='#e7d6a5';ctx.font='9px Georgia';ctx.textAlign='center';ctx.fillText(label,p.x,p.y-h/2-33)}}

