+:root{--gold:#e6c77a;--cream:#f1e7c9;--panel:rgba(13,18,24,.9);--line:rgba(231,205,137,.32)}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#10171b;color:var(--cream);font-family:Georgia,'Times New Roman',serif}button{font:inherit;color:inherit;cursor:pointer}#game{position:fixed;inset:0}canvas{display:block;width:100%;height:100%;touch-action:none}#vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at center,transparent 30%,rgba(3,8,12,.46) 100%)}.topbar{position:absolute;top:18px;left:20px;right:20px;display:flex;justify-content:space-between;pointer-events:none}.brand{font-size:13px;letter-spacing:.22em;color:#f1d89b;text-shadow:0 2px 6px #000}.brand small{display:block;font-size:10px;letter-spacing:.3em;color:#d4c6a0;margin-top:3px}.zone{font-size:12px;letter-spacing:.16em;color:#e3ddc6;text-shadow:0 2px 5px #000;text-align:right}.weather{font-size:10px;color:#c7c1ae;margin-top:5px;letter-spacing:.12em}#leftHud{position:absolute;left:20px;top:75px;width:272px;pointer-events:none}.portrait{display:flex;gap:12px;align-items:center;margin-bottom:12px}.avatar{width:53px;height:53px;border:1px solid #c9a65f;background:linear-gradient(145deg,#596b73,#17242c 65%,#a58a56);box-shadow:0 0 0 3px #151b1c,0 3px 12px #000;display:grid;place-items:center;font-size:27px;color:#edcf8a}.name{font-size:15px;color:#f1e2bd}.rank{color:#c8b98f;font-size:11px;margin-top:4px;letter-spacing:.08em}.barline{height:13px;margin:4px 0;background:#171c1e;border:1px solid #77705d;position:relative;box-shadow:0 2px 3px #000}.fill{height:100%;transition:width .25s}.hpfill{background:linear-gradient(#ba5848,#782e2a)}.mpfill{background:linear-gradient(#6198b7,#32546d)}.xpfill{background:linear-gradient(#d5b45c,#86703d)}.bartext{position:absolute;inset:0;text-align:center;font:9px/11px Georgia;color:white;text-shadow:0 1px 3px #000;letter-spacing:.05em}.statusline{display:flex;justify-content:space-between;color:#c7c0a9;font-size:10px;margin-top:6px;letter-spacing:.08em}#minimap{position:absolute;right:20px;top:68px;width:174px;height:174px;border:1px solid #c0a464;background:rgba(13,19,21,.78);box-shadow:0 2px 10px #000;pointer-events:none}.map-title{position:absolute;right:0;top:-18px;color:#dfcc98;font-size:10px;letter-spacing:.18em}#mapCanvas{width:100%;height:100%}#targetBox{position:absolute;top:265px;right:20px;width:205px;border:1px solid #a87b5c;background:var(--panel);padding:10px 12px;display:none;box-shadow:0 5px 15px #000}.target-name{font-size:14px;color:#e7d4a0}.target-sub{font-size:10px;color:#b8ae98;margin-top:3px}.target-hp{height:5px;background:#30201d;margin-top:8px}.target-fill{height:100%;background:#c95443}#questbox{position:absolute;right:20px;top:270px;width:205px;padding:12px;background:var(--panel);border-left:2px solid #bba15f;pointer-events:none}.qtitle{font-size:11px;color:#e4cc8f;letter-spacing:.14em;text-transform:uppercase;margin-bottom:7px}.qname{font-size:13px;color:#eee0bb}.qdesc{font-size:11px;color:#b7b09d;line-height:1.45;margin-top:5px}.qprogress{font-size:10px;color:#cfbf91;margin-top:8px}#bottom{position:absolute;left:50%;bottom:18px;transform:translateX(-50%);width:min(660px,calc(100% - 24px));display:flex;flex-direction:column;align-items:center;gap:8px;pointer-events:none}.combatlog{min-height:26px;max-width:100%;padding:5px 13px;background:rgba(8,12,15,.58);color:#e4d7b6;font-size:12px;text-align:center;text-shadow:0 1px 3px #000}.hotbar{display:flex;gap:6px;padding:7px 9px;background:rgba(12,17,20,.86);border:1px solid var(--line);box-shadow:0 3px 15px #000;pointer-events:auto}.slot{width:49px;height:49px;position:relative;border:1px solid #766e59;background:linear-gradient(145deg,#39434a,#191e20);display:grid;place-items:center;font-size:22px;box-shadow:inset 0 0 10px #000}.slot:hover{border-color:#e4c87f}.slot .key{position:absolute;top:2px;left:4px;font:9px Arial;color:#d6c69d}.slot .label{position:absolute;bottom:2px;font:8px Arial;color:#ddd}.slot.disabled{opacity:.55}#prompt{position:absolute;left:50%;bottom:105px;transform:translateX(-50%);padding:7px 15px;background:rgba(8,12,14,.83);border:1px solid #a78d56;color:#efdfb6;font-size:12px;display:none;white-space:nowrap;pointer-events:none}.hint,.right-hint{position:absolute;bottom:22px;color:#d3c9ad;font:10px Arial;letter-spacing:.1em;text-shadow:0 2px 4px #000;line-height:1.8;pointer-events:none}.hint{left:20px}.right-hint{right:20px;text-align:right}#toast{position:absolute;top:31%;left:50%;transform:translate(-50%,-50%);font-size:16px;letter-spacing:.12em;color:#f3d994;text-shadow:0 2px 9px #000;opacity:0;transition:opacity .4s;pointer-events:none;text-align:center}.modal{position:absolute;inset:0;background:rgba(3,7,9,.62);display:none;align-items:center;justify-content:center;padding:20px}.modal.open{display:flex}.window{width:min(520px,100%);max-height:85vh;overflow:auto;background:linear-gradient(145deg,rgba(34,42,44,.98),rgba(14,19,21,.98));border:1px solid #b49b60;box-shadow:0 8px 40px #000;padding:22px 24px;position:relative}.window:before{content:'';position:absolute;inset:5px;border:1px solid rgba(201,176,112,.18);pointer-events:none}.window h2{margin:0;color:#e4cd91;font-size:21px;font-weight:normal;letter-spacing:.1em}.window p{color:#c4bca7;font-size:13px;line-height:1.6}.close{position:absolute;right:15px;top:13px;background:none;border:0;color:#d6c69d;font-size:21px}.menurow{display:flex;justify-content:space-between;padding:10px 3px;border-bottom:1px solid rgba(213,190,126,.18);font-size:13px;color:#e7ddc3}.menurow span:last-child{color:#c9ae68}.action{padding:9px 15px;border:1px solid #a58d57;background:#594a2e;color:#f0dfb6;margin:4px 5px 0 0}.action:hover{background:#75613a}.dialogue{font-size:14px;line-height:1.7;color:#e0d5ba}.inventory-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:7px;margin:15px 0}.item{padding:11px 6px;background:#1a2224;border:1px solid #4f5144;text-align:center;font-size:11px;color:#d6c79f}.item strong{display:block;font-size:20px;margin-bottom:5px}.item small{color:#9e9989}#mobileControls{display:none;position:absolute;inset:auto 0 110px;justify-content:space-between;padding:0 20px;pointer-events:none}.stick{width:110px;height:110px;border:1px solid rgba(231,205,137,.3);border-radius:50%;background:rgba(8,13,16,.33);pointer-events:auto;touch-action:none;position:relative}.stick:after{content:'';width:38px;height:38px;position:absolute;left:35px;top:35px;border-radius:50%;background:rgba(207,187,129,.45);border:1px solid rgba(245,224,171,.55)}.touch-actions{display:grid;grid-template-columns:52px 52px;align-content:center;gap:8px;pointer-events:auto}.touch-actions button{height:48px;border-radius:50%;border:1px solid #b69a5e;background:rgba(28,32,31,.85);font-size:18px}@media(max-width:700px){.topbar{top:12px;left:12px;right:12px}.brand{font-size:10px}.brand small{font-size:8px}.zone{font-size:10px}#leftHud{top:55px;left:12px;width:210px}.avatar{width:42px;height:42px;font-size:21px}.name{font-size:13px}.rank{font-size:9px}.barline{height:11px}.bartext{font-size:8px;line-height:9px}#minimap{top:52px;right:12px;width:118px;height:118px}#targetBox{right:12px;top:180px;width:160px;padding:8px}#questbox{right:12px;top:224px;width:160px;padding:8px}.qtitle{font-size:9px}.qname{font-size:11px}.qdesc,.qprogress{font-size:9px}.hint,.right-hint{display:none}#bottom{bottom:10px}.hotbar{gap:4px;padding:5px}.slot{width:42px;height:42px;font-size:18px}.combatlog{font-size:10px;min-height:22px}.hotbar .slot:nth-child(n+6){display:none}#mobileControls{display:flex;bottom:100px}.modal{padding:12px}.window{padding:19px 16px}.window h2{font-size:18px}}
+</style></head><body><div id="game"><canvas id="world"></canvas><div id="vignette"></div><div class="topbar"><div class="brand">✦ MYTH OF EORWYN <small>THE QUIET FRONTIER</small></div><div class="zone">GREENHOLLOW MEADOWS<div class="weather">☼ &nbsp; CLEAR SKIES &nbsp; · &nbsp; DAY 01</div></div></div><div id="leftHud"><div class="portrait"><div class="avatar">♙</div><div><div class="name" id="playerName">Wayfarer</div><div class="rank">LEVEL <b id="levelText">1</b> &nbsp;·&nbsp; SWORD ADEPT</div></div></div><div class="barline"><div class="fill hpfill" id="hpFill"></div><span class="bartext" id="hpText"></span></div><div class="barline"><div class="fill mpfill" id="mpFill"></div><span class="bartext" id="mpText"></span></div><div class="barline"><div class="fill xpfill" id="xpFill"></div><span class="bartext" id="xpText"></span></div><div class="statusline"><span>◈ <b id="gilText">40</b> GIL</span><span id="regionText">WINDWARD COAST</span></div></div><div id="minimap"><span class="map-title">FIELD MAP</span><canvas id="mapCanvas" width="174" height="174"></canvas></div><div id="targetBox"><div class="target-name" id="targetName">—</div><div class="target-sub" id="targetSub">Hostile · Lv. 1</div><div class="target-hp"><div class="target-fill" id="targetFill"></div></div></div><div id="questbox"><div class="qtitle">✧ Current commission</div><div class="qname" id="questName">A Quiet Meadow</div><div class="qdesc" id="questDesc">The village sentries need help. Thin the meadow slimes.</div><div class="qprogress" id="questProgress">Slimes defeated: 0 / 3</div></div><div id="bottom"><div class="combatlog" id="log">The breeze carries the scent of wildflowers.</div><div class="hotbar"><button class="slot" data-action="attack"><span class="key">1</span>⚔<span class="label">Attack</span></button><button class="slot" data-action="cleave"><span class="key">2</span>✦<span class="label">Cleave</span></button><button class="slot" data-action="potion"><span class="key">3</span>⚗<span class="label">Potion</span></button><button class="slot" data-action="interact"><span class="key">E</span>♧<span class="label">Talk</span></button><button class="slot" data-action="inventory"><span class="key">I</span>▤<span class="label">Bag</span></button><button class="slot" data-action="rest"><span class="key">R</span>☾<span class="label">Rest</span></button></div></div><div class="hint"><b>WASD</b> MOVE · <b>CLICK</b> WALK / TARGET<br><b>SPACE</b> ATTACK · <b>E</b> INTERACT</div><div class="right-hint">1 ATTACK · 2 CLEAVE · 3 POTION<br>I INVENTORY · R REST · ESC MENU</div><div id="prompt">Press <b>E</b> to speak</div><div id="toast"></div><div id="mobileControls"><div class="stick" id="stick"></div><div class="touch-actions"><button data-action="attack">⚔</button><button data-action="cleave">✦</button><button data-action="interact">E</button><button data-action="potion">⚗</button></div></div><div class="modal" id="modal"><div class="window"><button class="close" id="closeModal">×</button><div id="modalContent"></div></div></div></div><script>
 const canvas=document.getElementById('world'),ctx=canvas.getContext('2d'),mapC=document.getElementById('mapCanvas'),mctx=mapC.getContext('2d');
 const W=2000,H=1350;let vw=innerWidth,vh=innerHeight,dpr=Math.min(devicePixelRatio||1,2),last=0,clock=0,cam={x:0,y:0};
 function resize(){vw=innerWidth;vh=innerHeight;dpr=Math.min(devicePixelRatio||1,2);canvas.width=vw*dpr;canvas.height=vh*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}addEventListener('resize',resize);resize();
