function drawTree(t){let p=worldToScreen(t.x,t.y),r=t.r;if(p.x<-r*2||p.x>vw+r*2||p.y<-r*2||p.y>vh+r*2)return;ctx.fillStyle='rgba(0,0,0,.24)';ctx.beginPath();ctx.ellipse(p.x+5,p.y+8,r*1.1,r*.48,0,0,7);ctx.fill();ctx.fillStyle='#604d36';ctx.fillRect(p.x-r*.12,p.y-r*.1,r*.24,r*.8);let colors=t.kind==='pine'?['#264a39','#315a42','#3e6849']:['#335642','#3d6345','#547447'];for(let j=0;j<3;j++){ctx.fillStyle=colors[(t.tone+j)%3];ctx.beginPath();ctx.ellipse(p.x+(j-1)*r*.33,p.y-r*.15-j*r*.26,r*.57,r*.55,0,0,7);ctx.fill()}ctx.strokeStyle='rgba(180,190,126,.18)';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(p.x-r*.35,p.y-r*.48,r*.28,r*.18,-.4,0,5);ctx.stroke()}
function drawProps(){for(const o of props){let p=worldToScreen(o.x,o.y);if(p.x<0||p.x>vw||p.y<0||p.y>vh)continue;let k=o.k;if(k<.53){ctx.fillStyle=k<.25?'#a1a071':'#d0b765';ctx.globalAlpha=.55;ctx.beginPath();ctx.arc(p.x,p.y,1.3,0,7);ctx.fill();ctx.globalAlpha=1}else if(k<.62){ctx.fillStyle='#827d65';ctx.beginPath();ctx.ellipse(p.x,p.y,3,2,0,0,7);ctx.fill()}else if(k<.7){ctx.strokeStyle='rgba(205,197,135,.38)';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(p.x+1,p.y-6);ctx.stroke();ctx.fillStyle='#d2bd67';ctx.beginPath();ctx.arc(p.x+1,p.y-6,1.5,0,7);ctx.fill()}}}
function drawCharacter(x,y,kind,phase=0,selected=false){let p=worldToScreen(x,y),pulse=Math.sin(clock*4+phase)*1.5;ctx.fillStyle='rgba(0,0,0,.3)';ctx.beginPath();ctx.ellipse(p.x,p.y+9,13,6,0,0,7);ctx.fill();if(kind==='player'||kind==='sentinel'||kind==='merchant'||kind==='elder'){ctx.fillStyle=kind==='player'?'#41566a':kind==='sentinel'?'#74613f':kind==='merchant'?'#795945':'#77775c';ctx.beginPath();ctx.moveTo(p.x-8,p.y+4);ctx.lineTo(p.x-6,p.y-7);ctx.lineTo(p.x,p.y-11);ctx.lineTo(p.x+6,p.y-7);ctx.lineTo(p.x+8,p.y+4);ctx.closePath();ctx.fill();ctx.fillStyle=kind==='player'?'#d3a778':'#cfb991';ctx.beginPath();ctx.arc(p.x,p.y-12,5,0,7);ctx.fill();if(kind==='player'){ctx.fillStyle='#b8c5c6';ctx.fillRect(p.x+6,p.y-13,2,16);ctx.strokeStyle='#e2d5b3';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(p.x+8,p.y-18);ctx.lineTo(p.x+8,p.y-8);ctx.stroke()}else{ctx.fillStyle='#e5d394';ctx.font='11px Georgia';ctx.textAlign='center';ctx.fillText(kind==='sentinel'?'!':'✦',p.x,p.y-23)} }else if(kind==='slime'){ctx.fillStyle='rgba(85,165,146,.78)';ctx.beginPath();ctx.ellipse(p.x,p.y-5+pulse,13,10,0,Math.PI,0);ctx.lineTo(p.x+13,p.y+4);ctx.quadraticCurveTo(p.x,p.y+13,p.x-13,p.y+4);ctx.closePath();ctx.fill();ctx.strokeStyle='rgba(196,236,205,.6)';ctx.lineWidth=1;ctx.stroke();ctx.fillStyle='#1b3d3b';ctx.beginPath();ctx.arc(p.x-4,p.y-4+pulse,1.4,0,7);ctx.arc(p.x+4,p.y-4+pulse,1.4,0,7);ctx.fill()}else{ctx.fillStyle='#634b37';ctx.beginPath();ctx.ellipse(p.x,p.y,14,9,0,0,7);ctx.fill();ctx.fillStyle='#423b30';ctx.beginPath();ctx.arc(p.x+8,p.y-5,6,0,7);ctx.fill();ctx.fillStyle='#dac9a4';ctx.beginPath();ctx.moveTo(p.x+8,p.y-10);ctx.lineTo(p.x+10,p.y-16);ctx.lineTo(p.x+12,p.y-9);ctx.fill()}if(selected){ctx.strokeStyle='rgba(240,209,127,.8)';ctx.lineWidth=1.5;ctx.beginPath();ctx.ellipse(p.x,p.y+11,17,6,0,0,7);ctx.stroke()}}
function drawMob(m){if(!m.alive)return;drawCharacter(m.x,m.y,m.type==='Meadow Slime'?'slime':'boar',m.phase,m===state.selected);let p=worldToScreen(m.x,m.y);if(m.hp<m.max||m===state.selected){ctx.fillStyle='#171916';ctx.fillRect(p.x-17,p.y-28,34,4);ctx.fillStyle='#be5947';ctx.fillRect(p.x-17,p.y-28,34*m.hp/m.max,4)}}
