function log(text){document.getElementById('log').textContent=text}let toastTimer;function toast(text){let el=document.getElementById('toast');el.textContent=text;el.style.opacity=1;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.style.opacity=0,2100)}function burst(x,y,text,color='#f2d58d',size=14){particles.push({x,y,text,color,size,life:1.2,max:1.2})}
function save(){try{localStorage.setItem('eorwyn-save',JSON.stringify({x:state.x,y:state.y,hp:state.hp,mp:state.mp,xp:state.xp,level:state.level,gil:state.gil,potions:state.potions,slimes:state.slimes,defeated:state.defeated,quest:state.quest,inventory:state.inventory,name:state.name,mobs:mobs.map(m=>({alive:m.alive,hp:m.hp,x:m.x,y:m.y}))}))}catch(e){}}
function load(){try{let s=JSON.parse(localStorage.getItem('eorwyn-save'));if(!s)return;Object.assign(state,s);if(s.mobs)s.mobs.forEach((v,i)=>{if(mobs[i])Object.assign(mobs[i],v)});document.getElementById('playerName').textContent=state.name}catch(e){}}
load();function updateHud(){const pct=(v,m)=>`${Math.max(0,Math.min(100,v/m*100))}%`;document.getElementById('hpFill').style.width=pct(state.hp,state.maxHp);document.getElementById('hpText').textContent=`HP ${Math.ceil(state.hp)} / ${state.maxHp}`;document.getElementById('mpFill').style.width=pct(state.mp,state.maxMp);document.getElementById('mpText').textContent=`MP ${Math.floor(state.mp)} / ${state.maxMp}`;document.getElementById('xpFill').style.width=pct(state.xp,state.next);document.getElementById('xpText').textContent=`EXP ${state.xp} / ${state.next}`;document.getElementById('levelText').textContent=state.level;document.getElementById('gilText').textContent=state.gil;document.getElementById('questProgress').textContent=state.quest===1?`Slimes defeated: ${Math.min(state.slimes,3)} / 3`:state.quest===2?'Return to Sentry Elowen for your reward.':state.quest===3?'Commission complete · Meadow safe':'Speak with Sentry Elowen to begin.';document.getElementById('targetBox').style.display=state.selected?.alive?'block':'none';if(state.selected?.alive){document.getElementById('targetName').textContent=state.selected.type;document.getElementById('targetSub').textContent=`Hostile · Level ${state.selected.level}`;document.getElementById('targetFill').style.width=(state.selected.hp/state.selected.max*100)+'%'}document.querySelectorAll('[data-action="potion"]').forEach(b=>b.classList.toggle('disabled',state.potions<1))}
function nearest(list,x=state.x,y=state.y){return list.map(o=>({o,d:Math.hypot(o.x-x,o.y-y)})).sort((a,b)=>a.d-b.d)[0]}
function gainXp(n){state.xp+=n;if(state.xp>=state.next){state.xp-=state.next;state.level++;state.next=Math.floor(state.next*1.35);state.maxHp+=22;state.maxMp+=10;state.hp=state.maxHp;state.mp=state.maxMp;toast(`LEVEL UP · ${state.level}`);burst(state.x,state.y-30,'LEVEL UP','#fff0ad',20);log('Your strength grows. HP and MP restored!')}updateHud()}
function killMob(m){m.alive=false;state.defeated++;state.gil+=Math.floor(rr(4,10));state.inventory['Slime Core']=(state.inventory['Slime Core']||0)+(m.type==='Meadow Slime'?1:0);if(m.type==='Meadow Slime'){state.slimes++;if(state.quest===1&&state.slimes>=3){state.quest=2;toast('COMMISSION READY · Return to Elowen');log('Three slimes defeated. Return to Sentry Elowen.')}}if(rand()<.18){state.potions++;state.inventory['Field Potion']=(state.inventory['Field Potion']||0)+1;log(`${m.type} defeated. It dropped a field potion!`)}else log(`${m.type} defeated · ${Math.floor(rr(4,10))} gil`);gainXp(m.type==='Meadow Slime'?32:45);burst(m.x,m.y-20,'+EXP','#f1d783',13);state.selected=null;setTimeout(()=>{if(m.alive===false){m.x=m.homeX+rr(-35,35);m.y=m.homeY+rr(-30,30);m.hp=m.max;m.alive=true}},14000);save()}
function hit(m,power=18){if(!m||!m.alive)return;if(Math.hypot(m.x-state.x,m.y-state.y)>78){state.move={x:m.x-35,y:m.y-12};state.selected=m;return}m.hp-=power;m.hit=.24;burst(m.x,m.y-24,`-${power}`,'#f1e8cf');log(`You strike ${m.type} for ${power} damage.`);if(m.hp<=0)killMob(m);updateHud()}
function doAttack(){if(state.dead)return;let m=state.selected;if(!m?.alive){let n=nearest(mobs.filter(a=>a.alive));if(!n||n.d>390){log('No foe in range. Click a nearby creature to target it.');return}m=n.o;state.selected=m;updateHud()}if(state.attackCd>0)return;state.attackCd=1.15;hit(m,Math.floor(rr(17,24))+state.level*2)}
function doCleave(){if(state.dead)return;if(state.cleaveCd>0){log('Cleave is not ready yet.');return}if(state.mp<15){log('Not enough MP for Crescent Cleave.');return}let nearby=mobs.filter(m=>m.alive&&Math.hypot(m.x-state.x,m.y-state.y)<104);if(!nearby.length){log('No foes close enough for Crescent Cleave.');return}state.mp-=15;state.cleaveCd=5;log('Crescent Cleave sweeps through nearby foes!');burst(state.x,state.y-14,'✧','#c8ebf0',27);nearby.forEach(m=>{m.hp-=34+state.level*3;m.hit=.3;burst(m.x,m.y-24,'-34','#bce6ed');if(m.hp<=0)killMob(m)});updateHud()}
function potion(){if(state.potions<1){log('Your field-potion pouch is empty.');return}if(state.hp>=state.maxHp){log('You are already at full health.');return}state.potions--;state.inventory['Field Potion']=Math.max(0,(state.inventory['Field Potion']||0)-1);state.hp=Math.min(state.maxHp,state.hp+46);burst(state.x,state.y-24,'+46 HP','#9ce0a7');log('You drink a field potion and recover health.');updateHud();save()}
