const modal=document.getElementById('modal'),modalContent=document.getElementById('modalContent');function openDialogue(title,text,choices=[]){modalContent.innerHTML=`<h2>${title}</h2><p class="dialogue">“${text}”</p><div>${choices.map((c,i)=>`<button class="action" data-choice="${i}">${c[0]}</button>`).join('')}</div>`;modal.classList.add('open');modalContent.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>choices[+b.dataset.choice][1]())}function closeModal(){modal.classList.remove('open')}
document.getElementById('closeModal').onclick=closeModal;modal.addEventListener('click',e=>{if(e.target===modal)closeModal()});
function openShop(){let html=`<h2>Tomas’ Field Supplies</h2><p>“A little preparation goes a long way. What can I get you?”</p><div class="menurow"><span>Field Potion · restores 46 HP</span><span>35 gil</span></div><p>You carry ${state.potions} potion${state.potions===1?'':'s'}.</p><button class="action" id="buyPotion">Buy a potion</button><button class="action" id="shopBye">Leave</button>`;modalContent.innerHTML=html;modal.classList.add('open');document.getElementById('shopBye').onclick=closeModal;document.getElementById('buyPotion').onclick=()=>{if(state.gil<35){log('You do not have enough gil.');return}state.gil-=35;state.potions++;state.inventory['Field Potion']=(state.inventory['Field Potion']||0)+1;log('Bought a field potion for 35 gil.');save();updateHud();openShop()}}
function openInventory(){modalContent.innerHTML=`<h2>Adventurer’s Satchel</h2><p>Useful things gathered on the road.</p><div class="inventory-grid"><div class="item"><strong>⚗</strong>Field Potion<small> × ${state.potions}</small></div><div class="item"><strong>◉</strong>Slime Core<small> × ${state.inventory['Slime Core']||0}</small></div><div class="item"><strong>✿</strong>Sunpetal<small> × ${state.inventory.Sunpetal||0}</small></div><div class="item"><strong>◈</strong>Gil<small> × ${state.gil}</small></div></div><div class="menurow"><span>Iron-bound longsword</span><span>Equipped · ATK 12</span></div><div class="menurow"><span>Traveler’s mantle</span><span>Equipped · DEF 4</span></div><p>Your journey is saved automatically on this device. This adventure works offline.</p>`;modal.classList.add('open')}
function showMenu(){modalContent.innerHTML=`<h2>Wayfarer’s Journal</h2><p>Welcome to Greenhollow. The village is a safe haven, but the meadow beyond has its dangers.</p><div class="menurow"><span>Progress</span><span>Level ${state.level} · ${state.defeated} foes defeated</span></div><div class="menurow"><span>Controls</span><span>WASD / tap to walk · Space to attack</span></div><div class="menurow"><span>Sound</span><span>Ambient silence</span></div><p>Progress saves automatically in your browser.</p><button class="action" id="resume">Return to the meadow</button><button class="action" id="reset">Begin a new journey</button>`;modal.classList.add('open');document.getElementById('resume').onclick=closeModal;document.getElementById('reset').onclick=()=>{if(confirm('Erase your local adventure and start over?')){localStorage.removeItem('eorwyn-save');location.reload()}}}
function action(a){if(a==='attack')doAttack();else if(a==='cleave')doCleave();else if(a==='potion')potion();else if(a==='interact')interact();else if(a==='inventory')openInventory();else if(a==='rest')doRest()}
