function stickMove(e){let r=stick.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),len=Math.max(1,Math.hypot(dx,dy)),mag=Math.min(1,len/36);stickInput={x:dx/len*mag,y:dy/len*mag};stick.style.setProperty('--dx',`${stickInput.x*34}px`);stick.style.setProperty('--dy',`${stickInput.y*34}px`)}}
function tick(dt){clock+=dt;state.gameTime=(state.gameTime+dt*.018)%24;state.attackCd=Math.max(0,state.attackCd-dt);state.cleaveCd=Math.max(0,state.cleaveCd-dt);state.invuln=Math.max(0,state.invuln-dt);let dx=0,dy=0;if(keys.KeyW||keys.ArrowUp)dy--;if(keys.KeyS||keys.ArrowDown)dy++;if(keys.KeyA||keys.ArrowLeft)dx--;if(keys.KeyD||keys.ArrowRight)dx++;dx+=stickInput.x;dy+=stickInput.y;let moving=!!(dx||dy);if(moving){let l=Math.hypot(dx,dy);dx/=l;dy/=l;state.x=Math.max(24,Math.min(W-24,state.x+dx*158*dt));state.y=Math.max(24,Math.min(H-24,state.y+dy*158*dt));state.face=dx>=0?1:-1;state.move=null;state.interactTarget=null}else if(state.move){let tx=state.move.x-state.x,ty=state.move.y-state.y,d=Math.hypot(tx,ty);if(d>5){state.x+=tx/d*Math.min(d,142*dt);state.y+=ty/d*Math.min(d,142*dt);state.face=tx>=0?1:-1}else{state.move=null;if(state.interactTarget){let n=state.interactTarget;state.interactTarget=null;if(Math.hypot(n.x-state.x,n.y-state.y)<88)interact()}}}
 for(const m of mobs){if(!m.alive)continue;m.hit=Math.max(0,m.hit-dt);m.attack=Math.max(0,m.attack-dt);let d=Math.hypot(state.x-m.x,state.y-m.y);if(d<156)m.aggro=true;if(m.aggro&&d<255){if(d>42){m.x+=(state.x-m.x)/d*48*dt;m.y+=(state.y-m.y)/d*48*dt}else if(m.attack<=0&&state.invuln<=0){m.attack=1.65;state.invuln=.48;let dmg=Math.floor(rr(5,10))+Math.max(0,m.level-state.level);state.hp-=dmg;burst(state.x,state.y-22,`-${dmg}`,'#ec8373');log(`${m.type} hits you for ${dmg} damage.`);if(state.hp<=0){state.hp=0;state.dead=true;state.autoAttack=false;setTimeout(()=>{state.x=940;state.y=690;state.hp=Math.ceil(state.maxHp*.55);state.mp=Math.ceil(state.maxMp*.5);state.dead=false;state.invuln=2;state.gil=Math.max(0,state.gil-8);state.selected=null;toast('You awaken in Greenhollow');log('The village healers brought you back. 8 gil lost.');updateHud();save()},1800)}}}else{m.aggro=false;m.x+=Math.sin(clock*.7+m.phase)*4*dt;m.y+=Math.cos(clock*.6+m.phase)*4*dt}}
 if(state.selected?.alive&&state.autoAttack&&!state.dead&&state.attackCd<=0&&Math.hypot(state.selected.x-state.x,state.selected.y-state.y)<75){state.attackCd=1.35;hit(state.selected,Math.floor(rr(17,24))+state.level*2)}
 for(let i=particles.length-1;i>=0;i--){particles[i].life-=dt;particles[i].y-=17*dt;if(particles[i].life<=0)particles.splice(i,1)}
 let near=nearestNpc();document.getElementById('prompt').style.display=near?'block':'none';if(near)document.getElementById('prompt').innerHTML=`Press <b>E</b> to speak with ${near.name}`;if(Math.floor(clock*2)%2===0)updateHud();if(Math.floor(clock)%8===0)save();
}
function frame(now){let dt=Math.min(.04,(now-last)/1000||0);last=now;tick(dt);drawScene();requestAnimationFrame(frame)}
updateHud();log('Welcome to Greenhollow. Seek Sentry Elowen in the village square.');requestAnimationFrame(frame);
</script></body></html>

